from typing import Any

from dotenv import load_dotenv
from langchain.messages import HumanMessage
from langchain.tools import tool
from tavily import TavilyClient

load_dotenv()
tavily_client = TavilyClient()


@tool
def web_search(query: str) -> dict[str, Any]:
    """Search the web for information"""
    print("web is running")
    return tavily_client.search(query)


multimodal_question = HumanMessage(
    content=[
        {
            "type": "text",
            "text": "List ingredients you can see inside this fridge, respond only with raw list",
        },
        {
            "type": "image",
            "base64": "",
            "mime_type": "image/png",
        },
    ]
)


system_prompt = """

You are a personal chef. The user will give you a list of ingredients they have left over in their house.

Using the web search tool, search the web for recipes that can be made with the ingredients they have.

Return recipe suggestions and eventually the recipe instructions to the user, if requested.

"""

from langchain.agents import create_agent

agent = create_agent(
    model="gpt-5-nano", tools=[web_search], system_prompt=system_prompt
)
response = agent.invoke({"messages": multimodal_question})

print(response["messages"][-1].content)

response = agent.invoke({"messages": response["messages"][-1].content})

print(response["messages"][-1].content)

